 <section id="menu"><div class="brand"><i class="brand-mark"></i> AEGIS TEMPORAL DIVISION</div><div class="hero"><div class="eyebrow">2089 · Chrono breach detected</div><h1><span class="title-line">Chrono-</span><span class="title-line">Trigger</span></h1><p><strong>Reality is coming apart.</strong> Pursue the rogue intelligence Aether through a fractured battlefield and reclaim the timeline—one impossible second at a time.</p><div class="actions"><button class="primary" id="start">Enter the rift <span>↗</span></button><span class="hint">WASD move &nbsp;·&nbsp; mouse aim &nbsp;·&nbsp; click fire</span></div></div><aside class="panel"><div class="panel-head"><span>Field briefing / 01</span><span class="blink">● LIVE</span></div><h2>Echoes of the Rift</h2><div class="sub">Operation: Broken Hour</div><p class="brief">Aether has split the city between 2089 and 1944. Secure the temporal anchor. Expect resistance from the corrupted.</p><div class="feature"><span class="feature-icon">↺</span><div><b>Chrono rewind</b><small>Reclaim ammo. Rewind their wounds, too.</small></div></div><div class="feature"><span class="feature-icon">⌁</span><div><b>Temporal echo</b><small>Your past self is your next flanking move.</small></div></div><div class="feature"><span class="feature-icon">◉</span><div><b>Unstable realities</b><small>Cover changes with the era. Adapt fast.</small></div></div><div class="panel-foot"><span>VEX / FIELD OPERATIVE</span><span>RIFT STABILITY 32%</span></div></aside></section>
 <section id="hud"><div class="topbar"><div class="mission"><small>AEGIS / FIELD INTERFACE</small><strong>OPERATION: BROKEN HOUR</strong></div><div class="era" id="era">2089 // NEON TOKYO<span>RIFT SHIFT IN 24</span></div></div><div class="objective">OBJECTIVE <b id="kills">ELIMINATE CORRUPTED · 0 / 6</b></div><div class="mapbox"><canvas id="minimap" width="104" height="104"></canvas></div><div class="center-note" id="note"></div><div class="crosshair"><i></i></div><div class="bottom-left"><div class="health"><div class="label">VITALS / STABLE</div><div class="health-num" id="hptext">100 <small>/ 100</small></div><div class="bar"><i id="hpbar"></i></div></div><div class="shield">◈ &nbsp;62</div></div><div class="abilities"><div class="ability"><div><strong>REWIND</strong><small>3 SEC LOCAL TIME</small></div><kbd>R</kbd></div><div class="ability"><div><strong>ECHO</strong><small>5 SEC GHOST</small></div><kbd>E</kbd></div><div class="ability"><div><strong>STASIS</strong><small>4 SEC / 1 CHARGE</small></div><kbd>Q</kbd></div></div><div class="bottom-right"><div class="weapon">Paradox Rifle</div><div class="weapon-sub" id="ammoType">PLASMA / PRESENT MODE</div><div class="ammo"><span id="ammo">24</span> <small>/ ∞</small></div></div></section>
 <div class="mobile-controls"><button class="joy" id="touchMove">MOVE</button><button class="fire" id="touchFire">FIRE</button><button class="rew" id="touchRewind">↺</button><button class="echo" id="touchEcho">ECHO</button></div><div class="banner" id="banner"><h2></h2><p></p></div><div class="pause" id="pause"><div><div class="eyebrow">Temporal link suspended</div><h2>Paused</h2><p>THE TIMELINE CAN WAIT.</p><button class="primary" id="resume">Resume mission</button></div></div></main>
 <script>
+(()=>{'use strict';
+const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#minimap'),mctx=mapCanvas.getContext('2d');
+const W=20,H=18,FOV=Math.PI*.37,MAX=24;
+const map2089=[
+'11111111111111111111','10000000000000000001','10111001011101110001','10000001000000000001','10101111011011011001','10001000000000000001','10101011101011101101','10000010000000100001','10111010111010101001','10000000000000100001','10111101101011101001','10000100000000000001','10110101111011101101','10000001000000000001','10111011011101111001','10000000000000000001','10000000000000000001','11111111111111111111'];
+const map1944=[
+'11111111111111111111','10000000000000000001','10111001011101110001','10000001000000000001','10101111011011011001','10001000000000000001','10101011101011101101','10000010000000100001','10111010111010101001','10000000000000100001','10111101101011101001','10000100000000000001','10110101111011101101','10000001000000000001','10111011011101111001','10000000000000000001','10000000000000000001','11111111111111111111'];
+let era=0,playing=false,paused=false,over=false,then=0,lastShift=0,eraTimer=25,damageFlash=0,noticeTimer=0,shotFlash=0,shake=0;
+let player={x:2.5,y:2.5,a:.18,hp:100,ammo:MAX,fireAt:0,walk:0};
+let enemies=[],particles=[],shots=[],history=[],echo=null,stasisUntil=0,stasisCharge=1,kills=0,moveKeys={},mouseDown=false,touchMove={x:0,y:0};
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),now=()=>performance.now()/1000;
+function makeEnemies(){const points=[[7.5,2.5],[13.5,3.5],[5.5,7.5],[16.5,7.5],[10.5,10.5],[3.5,14.5]];return points.map((p,i)=>({x:p[0],y:p[1],hp:i===5?120:70,max:i===5?120:70,alive:true,hitAt:0,attack:rand(2,5),phase:rand(0,6),boss:i===5}))}
+function resize(){const d=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();
+function isWall(x,y){const ix=Math.floor(x),iy=Math.floor(y);if(ix<0||iy<0||ix>=W||iy>=H)return true;return(era?map1944:map2089)[iy][ix]==='1'}
+function say(text,seconds=1.6){const n=document.querySelector('#note');n.textContent=text;n.style.opacity=1;noticeTimer=seconds}
+function changeEra(){era=1-era;eraTimer=25;lastShift=now();say(era?'ERA SHIFT // 1944 — THE IRON AGE':'ERA SHIFT // 2089 — NEON TOKYO',2.2);document.querySelector('#era').innerHTML=era?'1944 // IRON DISTRICT<span>ANACHRONISTIC THREATS DETECTED</span>':'2089 // NEON TOKYO<span>RIFT SHIFT IN 25</span>';document.querySelector('#ammoType').textContent=era?'KINETIC / PAST MODE':'PLASMA / PRESENT MODE';}
+function reset(){player={x:2.5,y:2.5,a:.18,hp:100,ammo:MAX,fireAt:0,walk:0};enemies=makeEnemies();particles=[];shots=[];history=[];echo=null;kills=0;era=0;eraTimer=25;lastShift=now();stasisCharge=1;stasisUntil=0;over=false;document.querySelector('#kills').textContent='ELIMINATE CORRUPTED · 0 / 6';document.querySelector('#ammo').textContent=MAX;document.querySelector('#hptext').innerHTML='100 <small>/ 100</small>';document.querySelector('#hpbar').style.width='100%';changeEra();era=0;document.querySelector('#era').innerHTML='2089 // NEON TOKYO<span>RIFT SHIFT IN 25</span>';document.querySelector('#ammoType').textContent='PLASMA / PRESENT MODE'}
+function start(){reset();playing=true;paused=false;document.querySelector('#menu').style.display='none';document.querySelector('#hud').style.display='block';document.querySelector('#pause').style.display='none';document.querySelector('#banner').style.opacity=0;say('ELIMINATE THE CORRUPTED',2);then=now();requestAnimationFrame(frame)}
+document.querySelector('#start').onclick=start;document.querySelector('#resume').onclick=()=>{paused=false;document.querySelector('#pause').style.display='none';then=now();requestAnimationFrame(frame)};
+function rayDistance(angle,max=20){let dx=Math.cos(angle),dy=Math.sin(angle),d=.02;while(d<max&&!isWall(player.x+dx*d,player.y+dy*d))d+=.025;return d}
+function blocked(x1,y1,x2,y2){let d=Math.hypot(x2-x1,y2-y1),steps=Math.ceil(d*12);for(let i=1;i<steps;i++){let t=i/steps;if(isWall(x1+(x2-x1)*t,y1+(y2-y1)*t))return true}return false}
+function canMove(x,y){return !isWall(x-.16,y-.16)&&!isWall(x+.16,y-.16)&&!isWall(x-.16,y+.16)&&!isWall(x+.16,y+.16)}
+function move(dt,dx,dy){if(canMove(player.x+dx,player.y))player.x+=dx;if(canMove(player.x,player.y+dy))player.y+=dy;if(Math.abs(dx)+Math.abs(dy)>.0001)player.walk+=dt*8}
+function shoot(isEcho=false){let t=now();if(!playing||paused||over)return;if(!isEcho&&t<player.fireAt)return;if(!isEcho&&player.ammo<=0){say('AMMO EMPTY — PRESS R TO REWIND',1);return}if(!isEcho){player.fireAt=t+.19;player.ammo--;document.querySelector('#ammo').textContent=player.ammo;shotFlash=.12;shots.push({time:t,x:player.x,y:player.y,a:player.a})}
+let target=null,best=.095;for(const e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.a),Math.cos(Math.atan2(dy,dx)-player.a));let aim=Math.atan2(.32,dist);if(Math.abs(diff)<best+aim&&!blocked(player.x,player.y,e.x,e.y)){best=Math.abs(diff);target=e}}
+if(target){if(!(now()<stasisUntil)){target.hp-=era?29:24;target.hitAt=t;for(let i=0;i<7;i++)particles.push({x:target.x,y:target.y,z:rand(.4,1.5),life:rand(.15,.55),max:.55,color:era?'#ffc078':'#56faff'});if(target.hp<=0){target.alive=false;kills++;document.querySelector('#kills').textContent=`ELIMINATE CORRUPTED · ${kills} / 6`;say(target.boss?'RIFT WARDEN ELIMINATED':'CORRUPTED ELIMINATED',1.2);if(kills>=6)finish(true)}}}
+}
+function finish(win){over=true;const b=document.querySelector('#banner');b.querySelector('h2').textContent=win?'Timeline stabilized':'Vex down';b.querySelector('p').textContent=win?'AETHER’S SIGNAL HAS WITHDRAWN · CLICK TO DEPLOY AGAIN':'THE RIFT CLAIMED THIS TIMELINE · CLICK TO REDEPLOY';b.style.opacity=1}
+function rewind(){if(!playing||paused||over)return;let t=now(),restore=new Set();for(const s of shots)if(t-s.time<=3.1&&s.target)restore.add(s.target);for(const s of shots){if(t-s.time<=3.1){let e=enemies[s.target];if(e)e.hp=Math.min(e.max,e.hp+24)}}player.ammo=MAX;document.querySelector('#ammo').textContent=MAX;shots=shots.filter(s=>t-s.time>3);say('LOCAL TIME REWOUND · AMMUNITION RESTORED',1.7);}
+// Fire records retain target identity so rewind can restore only recent wounds.

