function drawWorld(){const w=innerWidth,h=innerHeight,horizon=h*.49;ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,era?'#101316':'#071521');sky.addColorStop(.72,era?'#32322a':'#12333b');sky.addColorStop(1,era?'#70614c':'#19505a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon);let ground=ctx.createLinearGradient(0,horizon,0,h);ground.addColorStop(0,era?'#615342':'#163b42');ground.addColorStop(1,era?'#0c1012':'#071116');ctx.fillStyle=ground;ctx.fillRect(0,horizon,w,h-horizon);
// distant skyline and horizon light
ctx.globalAlpha=.35;for(let i=0;i<20;i++){let x=(i*173-player.x*23)%w;if(x<0)x+=w;let bh=28+(i*37%91);ctx.fillStyle=era?'#35342c':'#0b2029';ctx.fillRect(x,horizon-bh,w/25,bh)}ctx.globalAlpha=1;
let strips=Math.min(440,Math.max(220,Math.floor(w/2.5))),step=w/strips,depths=new Float32Array(strips),wallTops=new Float32Array(strips);for(let i=0;i<strips;i++){let offset=(i/strips-.5)*FOV,ang=player.a+offset,dx=Math.cos(ang),dy=Math.sin(ang),d=.02;while(d<22&&!isWall(player.x+dx*d,player.y+dy*d))d+=.025;d*=Math.cos(offset);depths[i]=d;let wallH=Math.min(h*2,h*.85/(d+.03)),top=horizon-wallH*.5;wallTops[i]=top;let wx=player.x+Math.cos(ang)*d,wy=player.y+Math.sin(ang)*d,sideX=Math.abs(wx-Math.round(wx)),sideY=Math.abs(wy-Math.round(wy)),edge=Math.min(sideX,sideY),shade=clamp(1-d/17,.15,1)*(edge<.045?.72:1)*(i%Math.max(1,Math.floor(strips/90))===0?.97:1);let tile=(Math.floor(wx)+Math.floor(wy))%3;let base=era?[151,126,91]:[28,105,117];let r=base[0]*shade*(tile===0?.8:1),g=base[1]*shade*(tile===2?.78:1),b=base[2]*shade;ctx.fillStyle=`rgb(${r|0},${g|0},${b|0})`;ctx.fillRect(i*step,top,step+1,wallH);
// inset seams, old masonry or future metallic paneling
if(i%Math.max(1,Math.floor(strips/38))===0){ctx.fillStyle=era?'#392f26':'#071a20';ctx.fillRect(i*step,top,Math.max(1,step),wallH);ctx.fillStyle=era?'#b18c5a':'#55e4d8';ctx.fillRect(i*step,top,Math.max(1,step),2);ctx.fillStyle=era?'#756047':'#0c3940';ctx.fillRect(i*step,top+wallH*.48,Math.max(1,step),1)}if(!era&&i%Math.floor(strips/21)===0){ctx.fillStyle='#56f4ed';ctx.globalAlpha=.45*shade;ctx.fillRect(i*step,top+wallH*.2,2,Math.max(2,wallH*.12));ctx.globalAlpha=1}}
// floor perspective lines
ctx.globalAlpha=era?.12:.16;ctx.strokeStyle=era?'#f4c27a':'#67f9ee';ctx.lineWidth=1;for(let y=0;y<9;y++){let p=(y+1)/9,yy=horizon+(h-horizon)*p*p;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(w,yy);ctx.stroke()}ctx.globalAlpha=1;
let objects=[];for(const e of enemies)if(e.alive)objects.push({kind:'enemy',x:e.x,y:e.y,data:e});if(echo)objects.push({kind:'echo',x:echo.x,y:echo.y,data:echo});objects.sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));for(const o of objects){let dx=o.x-player.x,dy=o.y-player.y,dist=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)-player.a;ang=Math.atan2(Math.sin(ang),Math.cos(ang));if(Math.abs(ang)>FOV*.7||dist<.1||blocked(player.x,player.y,o.x,o.y))continue;let sx=w/2+Math.tan(ang)/Math.tan(FOV/2)*w/2,sz=h*.68/(dist+.15)*(o.kind==='enemy'&&o.data.boss?1.32:1),sy=horizon+sz*.18;let rayIndex=clamp(Math.floor(sx/step),0,strips-1);if(depths[rayIndex]<dist-.1)continue;if(o.kind==='enemy')drawEnemy(sx,sy,sz,o.data,dist);else drawEcho(sx,sy,sz)}
// muzzle bloom / stasis shimmer / glass fracture edges
if(shotFlash>0){ctx.globalAlpha=shotFlash*4;ctx.fillStyle='#8effff';ctx.beginPath();ctx.arc(w/2,h*.53,rand(18,34),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;shotFlash-=.016}
if(now()<stasisUntil){ctx.fillStyle='#5cf4ee0a';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#8ffaffaa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(w/2,h*.51,Math.min(w,h)*.34,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.4;ctx.beginPath();ctx.arc(w/2,h*.51,Math.min(w,h)*.35,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
